<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue';
import { ask } from '@tauri-apps/plugin-dialog';
import { Plus, Pencil, Trash2, Trophy, Search, X, Award, CalendarDays } from 'lucide-vue-next';
import { rows, run } from '../db';
import { notify, selectedStudent } from '../store';
import type { Activity, Achievement } from '../types';

const sek=ref(2); const term=ref(''); const definitions=ref<Activity[]>([]); const selectedId=ref(0); const achievements=ref<Achievement[]>([]); const definitionDialog=ref(false); const editing=ref<Activity|null>(null); const pending=ref(false);
const def=ref({name:'',description:'',level_one:'',level_two:'',level_three:''});
const year=ref(''); const achievementInfo=ref(''); const level=ref<number|null>(null);
const selected=computed(()=>definitions.value.find(item=>item.additional_mint_activity_id===selectedId.value)??null);
const filtered=computed(()=>definitions.value.filter(item=>item.name.toLocaleLowerCase('de').includes(term.value.toLocaleLowerCase('de'))));
const currentAchievements=computed(()=>achievements.value.filter(item=>item.sek===sek.value));
async function loadDefinitions(preferred=selectedId.value){definitions.value=await rows<Activity>('SELECT additional_mint_activity_id,name,description,level_one,level_two,level_three,sek FROM additional_mint_activities WHERE sek=$1 ORDER BY name COLLATE NOCASE',[sek.value]);selectedId.value=definitions.value.some(a=>a.additional_mint_activity_id===preferred)?preferred:(definitions.value[0]?.additional_mint_activity_id??0);}
async function loadAchievements(){const id=selectedStudent.value?.student_id;if(!id){achievements.value=[];return;}achievements.value=await rows<Achievement>(`SELECT s.student_additional_mint_activities_id,a.name AS competition_name,a.sek,s.level,CASE s.level WHEN 1 THEN a.level_one WHEN 2 THEN a.level_two WHEN 3 THEN a.level_three ELSE 'Keine Punkte' END AS level_description,s.year,COALESCE(s.achievement_info,'') AS achievement_info FROM student_additional_mint_activities s JOIN additional_mint_activities a ON a.additional_mint_activity_id=s.additional_mint_activity_id WHERE s.student_id=$1 ORDER BY s.year DESC,a.name COLLATE NOCASE`,[id]);}
onMounted(async()=>{await loadDefinitions();await loadAchievements();});
watch(()=>selectedStudent.value?.student_id,loadAchievements);
watch(sek,async()=>{term.value='';level.value=null;await loadDefinitions();});
function addDefinition(){editing.value=null;def.value={name:'',description:'',level_one:'',level_two:'',level_three:''};definitionDialog.value=true;}
function editDefinition(){if(!selected.value)return;editing.value=selected.value;def.value={name:selected.value.name,description:selected.value.description??'',level_one:selected.value.level_one??'',level_two:selected.value.level_two??'',level_three:selected.value.level_three??''};definitionDialog.value=true;}
async function saveDefinition(){if(!def.value.name.trim())return;pending.value=true;try{if(editing.value){await run('UPDATE additional_mint_activities SET name=$1,description=$2,level_one=$3,level_two=$4,level_three=$5 WHERE additional_mint_activity_id=$6',[def.value.name.trim(),def.value.description,def.value.level_one,def.value.level_two,def.value.level_three,editing.value.additional_mint_activity_id]);}else{const result=await run('INSERT INTO additional_mint_activities (name,description,level_one,level_two,level_three,sek) VALUES ($1,$2,$3,$4,$5,$6)',[def.value.name.trim(),def.value.description,def.value.level_one,def.value.level_two,def.value.level_three,sek.value]);await loadDefinitions(result.lastInsertId);}if(editing.value)await loadDefinitions(editing.value.additional_mint_activity_id);definitionDialog.value=false;notify('Aktivität gespeichert.');}catch(e){notify(String(e),'error');}finally{pending.value=false;}}
async function deleteDefinition(){if(!selected.value)return;if(!await ask(`„${selected.value.name}“ und alle zugehörigen Einträge löschen?`,{title:'Aktivität löschen',kind:'warning'}))return;await run('DELETE FROM student_additional_mint_activities WHERE additional_mint_activity_id=$1',[selectedId.value]);await run('DELETE FROM additional_mint_activities WHERE additional_mint_activity_id=$1',[selectedId.value]);await loadDefinitions(0);await loadAchievements();notify('Aktivität und Einträge gelöscht.');}
async function addAchievement(l:number){if(!selectedStudent.value){notify('Wähle zuerst eine:n Schüler:in.','error');return;}if(!selected.value)return;const y=year.value===''?null:Number(year.value);if(y!==null&&(!Number.isInteger(y)||y<1900||y>2100)){notify('Das Jahr muss zwischen 1900 und 2100 liegen.','error');return;}await run('INSERT INTO student_additional_mint_activities (student_id,additional_mint_activity_id,level,year,achievement_info) VALUES ($1,$2,$3,$4,$5)',[selectedStudent.value.student_id,selectedId.value,l,y,achievementInfo.value.trim()||null]);year.value='';achievementInfo.value='';await loadAchievements();notify('Erreichte Stufe gespeichert.');}
async function removeAchievement(a:Achievement){if(!await ask(`Eintrag „${a.competition_name}“ löschen?`,{title:'Eintrag löschen',kind:'warning'}))return;await run('DELETE FROM student_additional_mint_activities WHERE student_additional_mint_activities_id=$1',[a.student_additional_mint_activities_id]);await loadAchievements();notify('Eintrag gelöscht.');}
</script>

<template>
 <div class="activity-toolbar"><div class="sek-toggle" role="group" aria-label="Schulstufe"><button :class="{active:sek===1}" @click="sek=1">Sek I</button><button :class="{active:sek===2}" @click="sek=2">Sek II</button></div><span v-if="selectedStudent" class="student-context activity-student">{{selectedStudent.name}}</span><span v-else class="missing-student">Keine:r ausgewählt</span></div>
 <div class="activity-layout"><section class="panel activity-library"><header class="panel-heading"><div><h2>Aktivitätskatalog</h2><p>{{filtered.length}} Einträge · {{sek===1?'Sek I':'Sek II'}}</p></div><button class="button primary compact-button" @click="addDefinition"><Plus :size="16"/>Hinzufügen</button></header><div class="activity-search"><Search :size="16"/><input v-model="term" placeholder="Aktivität suchen…"/></div><div class="activity-list"><button v-for="item in filtered" :key="item.additional_mint_activity_id" class="activity-option" :class="{active:item.additional_mint_activity_id===selectedId}" @click="selectedId=item.additional_mint_activity_id;level=null"><span class="activity-option-icon"><Trophy :size="17"/></span><span class="activity-option-copy"><b>{{item.name}}</b><small>{{item.description||item.level_one||'Aktivität'}}</small></span><span class="option-chevron">›</span></button><div v-if="!filtered.length" class="empty-mini">Keine passenden Aktivitäten gefunden.</div></div><footer class="panel-footer"><button class="text-button" :disabled="!selected" @click="editDefinition"><Pencil :size="14"/>Bearbeiten</button><button class="text-button danger-text" :disabled="!selected" @click="deleteDefinition"><Trash2 :size="14"/>Löschen</button></footer></section>
  <section class="panel levels-panel"><header class="panel-heading"><div><h2>{{selected?.name??'Aktivität auswählen'}}</h2><p>{{selected?.description||'Wähle eine Aktivität aus dem Katalog.'}}</p></div><span v-if="selected" class="activity-type-tag">{{sek===1?'SEK I':'SEK II'}}</span></header><div v-if="selected" class="levels-content"><div class="level-grid"><button v-for="n in [0,1,2,3]" :key="n" class="level-option" :class="{chosen:level===n}" @click="level=n"><span class="level-circle">{{n}}</span><span><b>{{n===0?'Keine Punkte':`Stufe ${n}`}}</b><small>{{n===0?'Ohne Punkte':n===1?selected.level_one:n===2?selected.level_two:selected.level_three||'Keine Angabe'}}</small></span></button></div><div class="record-form"><p class="form-section-title">Erfolg für {{selectedStudent?.name??'Schüler:in'}} eintragen</p><div class="form-grid"><label>Jahr <span class="optional">optional</span><input v-model="year" type="number" min="1900" max="2100" placeholder="z. B. 2025" :disabled="!selectedStudent"/></label><label>Ergebnis <span class="optional">optional</span><input v-model="achievementInfo" placeholder="Zusätzliche Angabe" :disabled="!selectedStudent"/></label><div class="span-2"><button class="button primary" :disabled="!selectedStudent||level===null" @click="addAchievement(level ?? 0)"><Plus :size="16"/>Erreichte Stufe hinzufügen</button><span v-if="level===null" class="optional inline-help">Wähle oben die erreichte Stufe.</span></div></div></div><div class="achievement-section"><div class="section-heading small-heading"><div><h3>Erreichte Stufen</h3><p>{{currentAchievements.length}} Einträge dieser Schulstufe</p></div></div><div v-if="currentAchievements.length" class="achievement-list"><article v-for="a in currentAchievements" :key="a.student_additional_mint_activities_id" class="achievement-row"><span class="achievement-icon"><Award :size="17"/></span><div class="achievement-copy"><b>{{a.competition_name}}</b><small><CalendarDays :size="12"/>{{a.year??'Jahr offen'}} · {{a.achievement_info||a.level_description||'Keine Punkte'}} · Stufe {{a.level}}</small></div><button class="icon-button danger-icon" title="Eintrag löschen" @click="removeAchievement(a)"><Trash2 :size="15"/></button></article></div><div v-else class="empty-inline">{{selectedStudent?'Für diese Schulstufe sind noch keine Erfolge erfasst.':'Wähle eine:n Schüler:in, um erreichte Stufen zu sehen.'}}</div></div></div><div v-else class="empty-state tall-empty"><span class="empty-icon"><Trophy :size="22"/></span><b>Wähle eine Aktivität</b><p>Die drei Leistungsstufen erscheinen hier zur Auswahl.</p></div></section></div>
 <div v-if="definitionDialog" class="modal-backdrop" @click.self="definitionDialog=false"><section class="modal-card wide-modal" role="dialog" aria-modal="true"><header class="modal-header"><div><p class="eyebrow">{{editing?'KATALOG BEARBEITEN':`NEUER EINTRAG · SEK ${sek}`}}</p><h2>{{editing?'Aktivität bearbeiten':'Aktivität hinzufügen'}}</h2></div><button class="icon-button" @click="definitionDialog=false"><X :size="18"/></button></header><div class="form-grid"><label class="span-2">Name<input v-model="def.name" autofocus required/></label><label class="span-2">Beschreibung<textarea v-model="def.description" rows="2"/></label><label>Stufe 1<input v-model="def.level_one"/></label><label>Stufe 2<input v-model="def.level_two"/></label><label class="span-2">Stufe 3<input v-model="def.level_three"/></label><footer class="modal-actions span-2"><button class="button secondary" @click="definitionDialog=false">Abbrechen</button><button class="button primary" :disabled="pending||!def.name.trim()" @click="saveDefinition">{{pending?'Speichern…':'Speichern'}}</button></footer></div></section></div>
</template>
